// Loop over input items and add a new field called 'myNewField' to the JSON of each one
const secret = $headers['x-ss-secret'];
const EXPECTED = 'X9a7QwLm2Zp4RtVb6Yc8HsJd0Nk3UfEi';

function badRequest(message, httpCode = 400) {
  return [{
    ok: false,
    httpCode,
    error: message,
  }];
}

if (!secret || secret !== EXPECTED) {
  return badRequest('Unauthorized', 401);
}

const body = $json;

const reason = body?.flag?.reason;
const article = body?.article;

if (!article?.id || !article?.title || !article?.content || !reason) {
  return badRequest('Missing required fields: article.id/title/content and flag.reason');
}

const allowedReasons = [
  'INAPPROPRIATE_LANGUAGE',
  'MISINFORMATION',
  'HATE_SPEECH',
  'VIOLENCE',
  'ADVERTISING',
  'WRONG_CATEGORY',
];

if (!allowedReasons.includes(reason)) {
  return badRequest('Invalid reason');
}

function validateDetails(detailsRaw, minLen = 20) {
  const t = String(detailsRaw ?? '').trim();

  // only whitespace / empty
  if (!t) return 'Details cannot be empty (not only whitespace).';

  // minimum length
  if (t.length < minLen) return `Details must be at least ${minLen} characters.`;

  // common junk (exact matches)
  const lower = t.toLowerCase();
  const junkExact = new Set([
    'test','testing','asdf','asdasd','qwer','qwerty','lol','lmao','idk','no','none','n/a','na',
    '?','??','???','????','!','!!','!!!','....','...'
  ]);
  if (junkExact.has(lower)) return 'Details look like test/junk text. Please be specific.';

  // repeated single character only (aaaaaa / !!!!!!)
  if (/^(.)\1{5,}$/u.test(t)) return 'Details cannot be only repeated characters.';

  // only punctuation/emojis/symbols: require at least one letter or digit
  if (!/[a-z0-9]/i.test(t)) return 'Details must contain words (not only punctuation/emojis).';

  // mostly punctuation/emojis: require >= 30% alphanumeric
  const alnumCount = (t.match(/[a-z0-9]/gi) || []).length;
  if (alnumCount / t.length < 0.30) return 'Details contain too many symbols/emojis. Please use words.';

  return null;
}

// Truncate to control cost/limits
const MAX_CHARS = 15000;
const content = String(article.content);
const trimmedContent = content.length > MAX_CHARS ? content.slice(0, MAX_CHARS) : content;

const out = {
  ok: true,
  reporter: { user_id: body?.reporter?.user_id ?? null },
  article: {
    id: Number(article.id),
    title: String(article.title),
    excerpt: String(article.excerpt ?? ''),
    content: trimmedContent,
    category_id: Number(article.category_id ?? 0),
    category_name: String(article.category_name ?? ''),
  },
  category: {
    id: Number(body?.category?.id ?? article.category_id ?? 0),
    name: String(body?.category?.name ?? article.category_name ?? ''),
    description: String(body?.category?.description ?? ''),
  },
  flag: {
    id: body?.flag?.id ?? null,
    reason,
    details: String(body?.flag?.details ?? ''),
    suggested_category_id: body?.flag?.suggested_category_id ?? null,
    suggested_category_name: String(body?.flag?.suggested_category_name ?? ''),
  },
};

if (reason === 'WRONG_CATEGORY' && !out.flag.suggested_category_id) {
  return badRequest('WRONG_CATEGORY requires flag.suggested_category_id');
}

return [out];

