// Loop over input items and add a new field called 'myNewField' to the JSON of each one
function clamp01(x) {
  if (Number.isNaN(x)) return null;
  if (x < 0) return 0;
  if (x > 1) return 1;
  return x;
}

// Depending on n8n version/node, the AI text may be in different places.
// We'll try several common ones:
const raw = $json;

const text =
  raw?.message?.content ??
  raw?.choices?.[0]?.message?.content ??
  raw?.text ??
  raw?.data ??
  raw?.content;

let obj;
try {
  obj = typeof text === 'string' ? JSON.parse(text) : text;
} catch (e) {
  obj = null;
}

if (!obj || typeof obj !== 'object') {
  return [{
    decision: 'needs_human',
    confidence: 0,
    reason_codes: ['AI_INVALID_JSON'],
    user_message: 'Submitted for admin review.',
    admin_notes: 'AI returned invalid JSON.',
  }];
}

let decision = String(obj.decision ?? 'needs_human');
let confidence = clamp01(Number(obj.confidence));
let reason_codes = Array.isArray(obj.reason_codes) ? obj.reason_codes.map(String) : [];
let user_message = String(obj.user_message ?? 'Submitted.');
let admin_notes = String(obj.admin_notes ?? '');

if (!['accept', 'reject', 'needs_human'].includes(decision)) {
  decision = 'needs_human';
  reason_codes.push('AI_INVALID_DECISION');
}

if (confidence === null) confidence = 0.0;

// Threshold tuning (edit later)
if (decision === 'accept' && confidence < 0.75) decision = 'needs_human';
if (decision === 'reject' && confidence > 0.40) decision = 'needs_human';

return [{
  decision,
  confidence,
  reason_codes,
  user_message,
  admin_notes,
}];
